<?php declare(strict_types=1); use N3\App\Content\PageMediaAttachment; use N3\App\Site\NavigationItem; use N3\App\Site\SiteIdentity; $page = $viewData['page']; $preview = (bool) ($viewData['preview'] ?? false); $media = ($viewData['media'] ?? null) instanceof PageMediaAttachment ? $viewData['media'] : null; $site = ($viewData['siteIdentity'] ?? null) instanceof SiteIdentity ? $viewData['siteIdentity'] : null; $navigation = is_array($viewData['navigation'] ?? null) ? $viewData['navigation'] : []; ?>
<header class="site-header"><a class="brand" href="/" aria-label="<?= $escape(($site?->name ?? 'N3') . ' home') ?>"><?php if ($site !== null && $site->logoPath !== ''): ?><img class="brand-logo" src="<?= $escape($site->logoPath) ?>" alt=""><?php else: ?><span class="brand-mark" aria-hidden="true"><?= $escape($site === null ? 'N3' : mb_substr($site->name, 0, 2, 'UTF-8')) ?></span><?php endif; ?><span><?= $escape($site?->name ?? 'N3') ?></span></a><?php if ($preview): ?><a href="/admin/pages/<?= $escape($page->id) ?>/edit">Back to editor</a><?php elseif ($navigation !== []): ?><nav aria-label="Primary"><?php foreach ($navigation as $item): if (!$item instanceof NavigationItem) { continue; } ?><a href="<?= $item->slug === 'home' ? '/' : '/pages/' . $escape($item->slug) ?>"<?= $item->pageId === $page->id ? ' aria-current="page"' : '' ?>><?= $escape($item->label) ?></a><?php endforeach; ?></nav><?php endif; ?></header>
<main class="public-page" id="main-content">
    <?php if ($preview): ?><div class="preview-banner" role="status"><strong>Preview:</strong> This <?= $escape($page->status) ?> page is visible only to administrators.</div><?php endif; ?>
    <article aria-labelledby="page-title"><header class="public-page-heading"><p class="eyebrow"><?= $preview ? 'Page preview' : $escape($site?->tagline ?? 'N3 page') ?></p><h1 id="page-title"><?= $escape($page->title) ?></h1><?php if ($page->excerpt !== ''): ?><p class="page-excerpt"><?= $escape($page->excerpt) ?></p><?php endif; ?></header><?php if ($media !== null): ?><figure class="page-lead-image"><img src="<?= $preview ? '/admin/media/' . $escape($media->publicId) . '/preview' : '/media/' . $escape($media->publicId) . '.webp' ?>" alt="<?= $escape($media->altText) ?>" width="<?= $escape($media->width) ?>" height="<?= $escape($media->height) ?>" decoding="async"></figure><?php endif; ?><div class="page-body"><?= nl2br($escape($page->body), false) ?></div></article>
</main>
<?php if (!$preview && $site !== null): ?><footer class="site-footer"><p><strong><?= $escape($site->name) ?></strong></p><p>Contact: <a href="mailto:<?= $escape($site->contactEmail) ?>"><?= $escape($site->contactEmail) ?></a></p></footer><?php endif; ?>
